//! Bit-exact receipt-chain parity against the Python verify.py.
//!
//! tests/data/parity_receipts.txt is generated by tools/gen_receipt_vectors.py:
//! 6 deterministic docs folded by Python's Folder(seed=0), with the exact
//! receipts, final head, and accumulator. The Rust chain must reproduce
//! every receipt digest and the final head bit-for-bit.

use std::fs;
use std::path::Path;

struct Vectors {
    doc_dim: usize,
    n_docs: usize,
    docs: Vec<Vec<i16>>,
    receipts: Vec<String>,
    head_step: u64,
    head_acc: String,
    head_state: String,
}

fn parse(path: &Path) -> Vectors {
    let text = fs::read_to_string(path).expect("parity_receipts.txt missing");
    let mut tokens = text.split_whitespace();

    let mut section = String::new();
    let mut count = 0usize;
    let mut values: Vec<String> = Vec::new();
    let mut sections: Vec<(String, Vec<String>)> = Vec::new();
    loop {
        let Some(tok) = tokens.next() else { break };
        if count == 0 {
            if !section.is_empty() {
                sections.push((std::mem::take(&mut section), std::mem::take(&mut values)));
            }
            section = tok.to_string();
            count = tokens.next().expect("count").parse().unwrap();
        } else {
            values.push(tok.to_string());
            count -= 1;
        }
    }
    if !section.is_empty() {
        sections.push((section, values));
    }

    let get = |name: &str| -> &[String] {
        &sections
            .iter()
            .find(|(n, _)| n == name)
            .unwrap_or_else(|| panic!("missing section {name}"))
            .1
    };

    let doc_dim = get("DOC_DIM")[0].parse().unwrap();
    let n_docs = get("N_DOCS")[0].parse().unwrap();
    let flat: Vec<i16> = get("DOCS").iter().map(|s| s.parse::<i64>().unwrap() as i16).collect();
    assert_eq!(flat.len(), n_docs * doc_dim);
    let docs = (0..n_docs).map(|i| flat[i * doc_dim..(i + 1) * doc_dim].to_vec()).collect();
    let receipts = (0..n_docs)
        .map(|i| get(&format!("RECEIPT_{i}"))[0].clone())
        .collect();
    Vectors {
        doc_dim,
        n_docs,
        docs,
        receipts,
        head_step: get("HEAD_STEP")[0].parse().unwrap(),
        head_acc: get("HEAD_ACC")[0].clone(),
        head_state: get("HEAD_STATE")[0].clone(),
    }
}

#[test]
fn receipts_match_python_bit_for_bit() {
    let v = parse(
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/data/parity_receipts.txt")
            .as_path(),
    );
    assert_eq!(v.doc_dim, memochain_core::DOC_DIM);

    // The same Folder(seed=0) as the Python reference: reuse the fold
    // parity vectors for the weights.
    let fold_text = fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/data/parity.txt")
            .as_path(),
    )
    .expect("parity.txt missing");
    let mut tokens = fold_text.split_whitespace();
    let mut sections: Vec<(String, Vec<i64>)> = Vec::new();
    let mut section = String::new();
    let mut count = 0usize;
    let mut values: Vec<i64> = Vec::new();
    loop {
        let Some(tok) = tokens.next() else { break };
        if count == 0 {
            if !section.is_empty() {
                sections.push((std::mem::take(&mut section), std::mem::take(&mut values)));
            }
            section = tok.to_string();
            count = tokens.next().unwrap().parse().unwrap();
        } else {
            values.push(tok.parse().unwrap());
            count -= 1;
        }
    }
    if !section.is_empty() {
        sections.push((section, values));
    }
    let get = |name: &str| -> &[i64] {
        &sections.iter().find(|(n, _)| n == name).unwrap().1
    };
    let heads = 11usize;
    let kd = 32usize;
    let vd = 32usize;
    let w_key = (0..heads)
        .map(|h| {
            let start = h * kd * kd;
            get("W_KEY")[start..start + kd * kd].iter().map(|&x| x as i16).collect()
        })
        .collect();
    let w_val = (0..heads)
        .map(|h| {
            let start = h * vd * kd;
            get("W_VAL")[start..start + vd * kd].iter().map(|&x| x as i16).collect()
        })
        .collect();
    let folder = memochain_core::Folder {
        w_key,
        w_val,
        beta: get("BETA")[0],
        decay: get("DECAY")[0],
    };

    let mut state = memochain_core::zero_state();
    let mut head: Option<memochain_core::receipt::ChainHead> = None;
    for (i, doc) in v.docs.iter().enumerate() {
        let (s, receipt, h) =
            memochain_core::receipt::write_with_receipt(&folder, &state, doc, head.as_ref());
        assert_eq!(
            receipt.digest, v.receipts[i],
            "receipt {i} mismatch: python={} rust={}",
            v.receipts[i], receipt.digest
        );
        state = s;
        head = Some(h);
    }
    let head = head.expect("at least one doc");
    assert_eq!(head.step, v.head_step);
    assert_eq!(head.accumulator, v.head_acc);
    assert_eq!(head.state_digest, v.head_state);
    assert!(memochain_core::receipt::verify_chain(&folder, &v.docs, &head));
}
